value.content:
:root {
  --bg: #0b0f14;
  --panel: #131a23;
  --panel-2: #0e141c;
  --border: #223041;
  --text: #e8eef5;
  --muted: #8b98a8;
  --accent: #4da3ff;
  --accent-2: #7cc4ff;
  --green: #2fd48c;
  --amber: #ffb454;
  --red: #ff6b6b;
  --grid: #182230;
  --grid-strong: #24354a;
  --radius: 16px;
  --radius-sm: 10px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, "Segoe UI", Roboto, "Inter", "Helvetica Neue", Arial, sans-serif;
  font-size: 15px;
}

/* ---------- Kopfzeile ---------- */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 24px;
  border-bottom: 1px solid var(--border);
  background: linear-gradient(180deg, #101724 0%, var(--bg) 100%);
  position: sticky;
  top: 0;
  z-index: 5;
}
.brand { display: flex; align-items: center; gap: 14px; }
.brand h1 { font-size: 20px; margin: 0; letter-spacing: 0.4px; }
.brand-sub { margin: 2px 0 0; color: var(--muted); font-size: 13px; }
.brand-pulse {
  font-size: 22px;
  color: var(--green);
  width: 44px; height: 44px;
  display: flex; align-items: center; justify-content: center;
  background: rgba(47, 212, 140, 0.1);
  border: 1px solid rgba(47, 212, 140, 0.35);
  border-radius: 14px;
}

.container { max-width: 1200px; margin: 0 auto; padding: 24px; }

/* ---------- Karten / Buttons ---------- */
.card {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
}

.btn {
  border: 1px solid var(--border);
  background: var(--panel-2);
  color: var(--text);
  padding: 10px 18px;
  border-radius: 999px;
  font-size: 15px;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.05s;
}
.btn:active { transform: translateY(1px); }
.btn-primary { background: #1b2738; }
.btn-primary:hover { background: #223145; }
.btn-accent {
  background: var(--accent);
  border-color: var(--accent);
  color: #06121f;
  font-weight: 600;
}
.btn-accent:hover { background: var(--accent-2); }
.btn-accent:disabled { background: #243144; border-color: #243144; color: #5d6b7d; cursor: not-allowed; }
.btn-ghost { background: transparent; }
.btn-ghost:hover { background: var(--panel-2); }
.btn-big { padding: 14px 34px; font-size: 17px; }

/* ---------- Auswahl-Screen ---------- */
.select-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}
.pick-card h2 { margin: 0 0 6px; font-size: 17px; }
.hint { margin: 0 0 16px; color: var(--muted); font-size: 13.5px; }
.pick-value {
  font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  font-size: 13.5px;
  color: var(--accent-2);
  background: var(--panel-2);
  border: 1px dashed var(--border);
  border-radius: var(--radius-sm);
  padding: 10px 12px;
  margin-bottom: 14px;
  word-break: break-all;
  min-height: 40px;
}
.pick-value.empty { color: var(--muted); }
.start-row { display: flex; justify-content: center; margin-top: 28px; }

.record-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 14px;
}
.record-row label { color: var(--muted); font-size: 14px; white-space: nowrap; }
.record-row select {
  flex: 1;
  background: var(--panel-2);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 8px 10px;
  font-size: 14px;
}
.record-note { color: var(--muted); font-size: 12.5px; margin: 10px 0 0; }

/* ---------- Player ---------- */
.player-grid {
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: 20px;
  align-items: stretch;
}
.video-col { padding: 12px; display: flex; }
.video-col video {
  width: 100%;
  border-radius: 12px;
  background: #000;
  outline: none;
}

.stats-col { display: flex; flex-direction: column; gap: 20px; }
.stat-card { text-align: center; padding: 16px; }
.bpm-big {
  font-size: 64px;
  font-weight: 700;
  line-height: 1.1;
  color: var(--green);
  font-variant-numeric: tabular-nums;
  transition: color 0.3s;
}
.stat-sub { color: var(--muted); font-size: 13px; margin-bottom: 14px; }
.unit { color: var(--muted); font-size: 12px; }
.stat-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
  padding: 7px 4px;
  border-top: 1px solid var(--btnborder, var(--border));
  font-size: 14px;
  color: var(--muted);
}
.stat-row b { color: var(--text); font-variant-numeric: tabular-nums; font-size: 15px; }

.controls-card h3 { margin: 0 0 12px; font-size: 15px; }
.ctl {
  display: grid;
  grid-template-columns: 1fr auto auto;
  align-items: center;
  gap: 8px;
  padding: 8px 2px;
  font-size: 13.5px;
  color: var(--muted);
}
.num {
  width: 74px;
  background: var(--panel-2);
  border: 1px solid var(--border);
  color: var(--text);
  border-radius: 8px;
  padding: 6px 8px;
  text-align: right;
  font-size: 14px;
}

/* ---------- Diagramm ---------- */
.chart-card { margin-top: 20px; padding: 0; overflow: hidden; }
.tabs {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border);
  flex-wrap: wrap;
}
.tab {
  border: none;
  background: transparent;
  color: var(--muted);
  padding: 8px 16px;
  border-radius: 999px;
  font-size: 14px;
  cursor: pointer;
}
.tab:hover { color: var(--text); background: var(--panel-2); }
.tab.active { background: rgba(77, 163, 255, 0.16); color: var(--accent-2); }
.tab-tools { margin-left: auto; display: flex; gap: 14px; }
.chk {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-size: 13px;
  cursor: pointer;
}
.chk input { accent-color: var(--accent); }

.canvas-wrap { position: relative; }
#chart { display: block; width: 100%; height: 280px; }
.chart-legend {
  position: absolute;
  top: 10px;
  right: 14px;
  display: flex;
  gap: 14px;
  font-size: 12px;
  color: var(--muted);
  pointer-events: none;
}
.chart-legend span::before {
  content: "—";
  margin-right: 5px;
  font-weight: 700;
}
.footnote { color: var(--muted); font-size: 12.5px; }

/* ---------- Modal / Browser ---------- */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(3, 6, 10, 0.72);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 20;
}
.modal {
  width: min(760px, 94vw);
  max-height: 82vh;
  display: flex;
  flex-direction: column;
  padding: 0;
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.55);
}
.modal-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px 10px;
}
.modal-head h2 { margin: 0; font-size: 17px; }
.breadcrumb {
  padding: 4px 20px 12px;
  color: var(--accent-2);
  font-family: ui-monospace, Menlo, Consolas, monospace;
  font-size: 13px;
  border-bottom: 1px solid var(--border);
  word-break: break-all;
}
.browser-list { overflow-y: auto; padding: 8px; flex: 1; }
.browser-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  font-size: 14.5px;
}
.browser-item:hover { background: var(--panel-2); }
.browser-item.selected { background: rgba(77, 163, 255, 0.14); }
.browser-item .ico { width: 20px; text-align: center; }
.browser-item .size { margin-left: auto; color: var(--muted); font-size: 12.5px; }
.modal-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 20px;
  border-top: 1px solid var(--border);
}
.muted { color: var(--muted); font-size: 13px; }
.modal-empty { padding: 30px; text-align: center; color: var(--muted); }

@media (max-width: 900px) {
  .select-grid, .player-grid { grid-template-columns: 1fr; }
}

