    document.querySelector('[data-tab="ecg"]').click();
  });
  await new Promise((r) => setTimeout(r, 400));
  console.log('EKG-Tab (10s offset, 30s mittel):', JSON.stringify(await canvasStats()));

  console.log('errors:', errors.length ? errors : 'none');
  await browser.close();
})();
