const puppeteer = require('puppeteer-core');
(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/usr/bin/chromium', headless: 'new',
    args: ['--no-sandbox', '--disable-gpu', '--mute-audio', '--autoplay-policy=no-user-gesture-required'],
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1280, height: 1400 });
  const errors = [];
  page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
  page.on('response', (r) => { if (r.status() === 404) errors.push('404: ' + r.url()); });
  await page.goto('http://127.0.0.1:8765/?video=videos/beispiel.mp4&ecg=beispieldaten&record=1',
    { waitUntil: 'networkidle0', timeout: 30000 });
  await new Promise((r) => setTimeout(r, 1200));

  // 1) direkter JS-Klick
  await page.evaluate(() => document.querySelector('[data-tab="hr"]').click());
  await new Promise((r) => setTimeout(r, 400));
  console.log('JS-click tab =', await page.evaluate(() => window.ekgState.tab));

  // zurück zu ecg, dann echter Mausklick mit ElementCheck
  await page.evaluate(() => document.querySelector('[data-tab="ecg"]').click());
  const btnInfo = await page.evaluate(() => {
    const b = document.querySelector('[data-tab="hr"]');
    const r = b.getBoundingClientRect();
    const el = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
    return { rect: { x: r.x, y: r.y, w: r.width, h: r.height }, hit: el ? el.outerHTML.slice(0, 80) : null };
  });
  console.log('tab-button rect/hit:', JSON.stringify(btnInfo));
  const vp = await page.evaluate(() => ({ w: window.innerWidth, h: window.innerHeight, dpr: window.devicePixelRatio }));
  console.log('viewport:', JSON.stringify(vp));
  await page.click('[data-tab="hr"]');
  await new Promise((r) => setTimeout(r, 400));
  console.log('Maus-Klick tab =', await page.evaluate(() => window.ekgState.tab));
  await page.evaluate(() => document.querySelector('[data-tab="ecg"]').click());

  console.log('404s + Fehler:', errors.length ? errors : 'none');
  await browser.close();
})();
