(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/usr/bin/chromium', headless: 'new',
    args: ['--no-sandbox', '--disable-gpu', '--mute-audio', '--autoplay-policy=no-user-gesture-required'],
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1280, height: 1400 });
  const errors = [];
  page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
  page.on('response', (r) => { if (r.status() >= 400) errors.push(r.status() + ': ' + r.url()); });
  await page.goto('http://127.0.0.1:8765/?video=videos/beispiel.mp4&ecg=beispieldaten&record=1',
    { waitUntil: 'networkidle0', timeout: 30000 });
  await new Promise((r) => setTimeout(r, 1200));

  const stats = () => page.evaluate(() => {
    const c = document.getElementById('chart');
    const d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data;
    let green = 0, blue = 0, red = 0, purple = 0, white = 0;
    for (let i = 0; i < d.length; i += 4) {
      const r = d[i], g = d[i+1], b = d[i+2];
      if (g > 120 && g - r > 40) green++;
      if (b > 150 && b - r > 60) blue++;
      if (r > 150 && r - b > 60) red++;
      if (r > 100 && b > 150 && b - g > 40) purple++;
      if (r > 200 && g > 200 && b > 200) white++;
    }
    return { green, blue, red, purple, white };
  });

  const res = {};
  res.ecg = await stats();
  await page.click('[data-tab="hr"]');
  await new Promise((r) => setTimeout(r, 400));
  res.hr = await stats();

  // Seek über Klick auf die Timeline
  const t0 = await page.evaluate(() => document.getElementById('video').currentTime);
  const box = await page.evaluate(() => {
    const r = document.getElementById('chart').getBoundingClientRect();
    return { x: r.left + r.width / 2, y: r.top + r.height / 2, w: r.width };
  });
  const expected = await page.evaluate(() => {
    const c = document.getElementById('chart');
    const r = c.getBoundingClientRect();
    const px = r.left + r.width / 2;
    const w = window.ekgState;
    return ((px - r.left - 44) / (r.width - 52)) * w.data.duration;
  });
  await page.mouse.click(box.x, box.y);
  await new Promise((r) => setTimeout(r, 800));
  const t1 = await page.evaluate(() => document.getElementById('video').currentTime);
  res.seek = { before: +t0.toFixed(1), after: +t1.toFixed(1), expected: +expected.toFixed(1) };

  await page.click('[data-tab="dhr"]');
  await new Promise((r) => setTimeout(r, 400));
  res.dhr = await stats();

  console.log(JSON.stringify(res, null, 2));
  console.log('Fehler:', errors.length ? errors : 'none');
  await browser.close();
})();
EOF
