const puppeteer = require('puppeteer-core');
(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/usr/bin/chromium', headless: 'new',
    args: ['--no-sandbox', '--disable-gpu', '--mute-audio'],
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1280, height: 1000 });
  const errors = [];
  page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
  await page.goto('http://127.0.0.1:8765/', { waitUntil: 'networkidle0', timeout: 30000 });

  // Video-Picker
  await page.click('#btn-pick-video');
  await new Promise((r) => setTimeout(r, 400));
  let modal = await page.evaluate(() => !document.getElementById('modal').hidden);
  console.log('Modal offen:', modal);
  await page.evaluate(() => [...document.querySelectorAll('.browser-item')].find(n => n.textContent.includes('videos')).click());
  await new Promise((r) => setTimeout(r, 400));
  await page.evaluate(() => [...document.querySelectorAll('.browser-item')].find(n => n.textContent.includes('beispiel.mp4')).click());
  await new Promise((r) => setTimeout(r, 300));
  console.log('Video-Label:', await page.evaluate(() => document.getElementById('pick-video-label').textContent));
  console.log('Modal zu:', await page.evaluate(() => document.getElementById('modal').hidden));

  // EKG-Ordner-Picker
  await page.click('#btn-pick-ecg');
  await new Promise((r) => setTimeout(r, 400));
  await page.evaluate(() => [...document.querySelectorAll('.browser-item')].find(n => n.textContent.includes('beispieldaten')).click());
  await new Promise((r) => setTimeout(r, 400));
  await page.click('#modal-folder-confirm');
  await new Promise((r) => setTimeout(r, 600));
  console.log('EKG-Label:', await page.evaluate(() => document.getElementById('pick-ecg-label').textContent));
  console.log('Messungen:', await page.evaluate(() => document.getElementById('record-select').textContent));
  console.log('Record-Row sichtbar:', await page.evaluate(() => !document.getElementById('record-row').hidden));
  console.log('Start aktiv:', await page.evaluate(() => !document.getElementById('btn-start').disabled));

  // Start
  await page.click('#btn-start');
  await new Promise((r) => setTimeout(r, 2000));
  console.log('Player sichtbar:', await page.evaluate(() => !document.getElementById('view-player').hidden));
  console.log('BPM:', await page.evaluate(() => document.getElementById('bpm-now').textContent));
  console.log('Fehler:', errors.length ? errors : 'none');
  await browser.close();
})();
